SELECT id, code, create_user_id AS createUserId, create_user_name AS createUserName, create_time AS createTime, name, approve_status AS approveStatus, phase, grade_id AS gradeId, category_id AS categoryId , disabled AS disabled, srm_disabled AS srmDisabled, pay_method_id AS payMethodId, payment_condition as paymentCondition, purchase_user_id AS purchaseUserId, purchase_user_name AS purchaseUserName, approve_time as approveTime FROM supplier WHERE ${params.sqlMap.default} AND is_deleted=FALSE ORDER BY
${item.field} ${item.sort}
create_time DESC

SELECT id, code, create_user_id AS createUserId, create_user_name AS createUserName, create_time AS createTime, name, approve_status AS approveStatus, phase, grade_id AS gradeId, category_id AS categoryId , disabled AS disabled, srm_disabled AS srmDisabled, pay_method_id AS payMethodId, payment_condition as paymentCondition, purchase_user_id AS purchaseUserId, purchase_user_name AS purchaseUserName, approve_time as approveTime FROM supplier WHERE ${params.sqlMap.default} AND is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
create_time DESC

SELECT id,code,name,disabled,approve_status FROM supplier WHERE is_deleted=FALSE
and approve_status = #{approveStatus}
AND category_id IN (SELECT id FROM dict_basic WHERE is_deleted= FALSE AND type=#{type} AND value=#{value} ) ORDER BY create_time DESC
